import { isDeepStrictEqual } from "node:util";
import OpenAI from "openai";
import { Agent, Runner, computerTool, tool } from "@openai/agents-core";
import { OpenAIResponsesModel } from "@openai/agents-openai";

// The provider reply reached the capability owner, but cannot enter the SDK loop.
export class RetainedResponseNotAdmitted extends Error {}

// Managed Responses can report unknown counters as null at any level of a
// token breakdown. The SDK accepts omitted counters and nested numeric maps.
function omitUnknownTokenDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) return;
  for (const [key, value] of Object.entries(details)) {
    if (value === null) delete details[key];
    else if (typeof value === "object") omitUnknownTokenDetails(value);
  }
}

// Use the SDK's protocol conversion, but keep dispatch, retained originals and
// retry policy with the existing capability owner. Never construct a usable
// default network client here, even when OPENAI_API_KEY is present.
class RetainedResponsesModel extends OpenAIResponsesModel {
  constructor({ model, dispatch }) {
    super(
      new OpenAI({
        apiKey: "unused-caller-owned-transport",
        maxRetries: 0,
        fetch: async () => {
          throw new Error("Agent requests require the caller-owned transport");
        },
      }),
      model,
    );
    this.store = false;
    this.dispatch = dispatch;
  }

  admitsCompletion(response) {
    return response.model === this._model && !response.error;
  }

  async _fetchResponse(request, stream) {
    if (stream) throw new Error("Retained agent transport does not stream");
    request.signal?.throwIfAborted();
    const { requestData, signal } = this._buildResponsesCreateRequest(
      request,
      false,
    );
    if (requestData.model !== this._model)
      throw new Error("Agent model must match the selected transport model");
    if (requestData.store !== undefined && requestData.store !== this.store)
      throw new Error("Agent storage mode must match the capability owner");
    const body = structuredClone({ ...requestData, store: this.store });
    // The callback must retain the original response (including failed HTTP
    // responses) before returning or throwing. A throw is never replayed here.
    const response = await this.dispatch(body, { signal });
    signal?.throwIfAborted();
    // Preserve the synchronous capability contract before the SDK can execute
    // tools or start another turn. No-retry settings alone do not prevent a
    // queued/empty response from becoming another SDK dispatch.
    if (response?.status !== "completed" || !this.admitsCompletion(response))
      throw new RetainedResponseNotAdmitted(
        "Retained agent response is not an admitted completion",
      );
    const sdkResponse = structuredClone(response);
    omitUnknownTokenDetails(sdkResponse.usage?.input_tokens_details);
    omitUnknownTokenDetails(sdkResponse.usage?.output_tokens_details);
    return sdkResponse;
  }

  async getResponse(request) {
    return super.getResponse({ ...request, tracing: false });
  }

  getStreamedResponse() {
    throw new Error("Retained agent transport does not stream");
  }
}

// The SDK gives Agent.model precedence over Runner.config.model. Check each
// model call, including continuations, before an agent-supplied model can run.
class RetainedRunner extends Runner {
  run(agent, input, options = {}) {
    const callerFilter = options.callModelInputFilter;
    const filter = (args) => {
      if (args.agent.model)
        throw new Error("Agent must use the owner-selected transport model");
      return callerFilter ? callerFilter(args) : args.modelData;
    };
    filter.preserveInputIdentity = callerFilter?.preserveInputIdentity === true;
    return super.run(agent, input, {
      ...options,
      callModelInputFilter: filter,
    });
  }
}

/**
 * SDK execution engine for Planner or Runner, not another product agent.
 * The caller supplies the agent, tools, dispatch records and operation state.
 * No provider retry or remote trace export is enabled by this engine.
 */
export function createRetainedAgentRunner(options) {
  return retainedRunner(options, RetainedResponsesModel);
}

function retainedRunner({ model, dispatch, store }, Model) {
  if (typeof model !== "string" || model.trim() === "")
    throw new TypeError("An explicit agent model is required");
  if (typeof dispatch !== "function")
    throw new TypeError("A caller-owned agent dispatch is required");
  if (typeof store !== "boolean")
    throw new TypeError("An explicit agent storage mode is required");
  return new RetainedRunner({
    // String model selection happens before the per-call filter.
    modelProvider: {
      getModel() {
        throw new Error("Agent must use the owner-selected transport model");
      },
    },
    model: new Model({ model, dispatch, store }),
    modelSettings: { retry: { maxRetries: 0 } },
    tracingDisabled: true,
    traceIncludeSensitiveData: false,
  });
}

function isActionCall(item) {
  return item?.type === "computer_call" || item?.type === "function_call";
}

// The computer host owns the action loop. End the SDK turn after protocol
// conversion, before the SDK can validate, group or execute tools itself.
class ComputerProposalReceived extends Error {
  constructor(output) {
    super("Computer proposal received");
    this.callIds = output.filter(isActionCall).map((item) => item.callId);
  }
}

// Only the single-turn computer proposal below can use the original host's
// completion policy. It cannot execute tools or initiate a second dispatch.
class ComputerProposalModel extends RetainedResponsesModel {
  async getResponse(request) {
    const proposal = await super.getResponse(request);
    request.signal?.throwIfAborted();
    throw new ComputerProposalReceived(proposal.output);
  }

  admitsCompletion() {
    return true;
  }
}

function hostOwnedAction() {
  throw new Error("Only the computer host may carry out an action");
}

// SDK tool definitions advertise the current operations. The host validates
// the complete original response and performs its actions in provider order.
function computerActionTool(definition) {
  if (definition.type === "computer") {
    return computerTool({
      name: "computer",
      needsApproval: true,
      computer: {
        screenshot: hostOwnedAction,
        click: hostOwnedAction,
        doubleClick: hostOwnedAction,
        drag: hostOwnedAction,
        keypress: hostOwnedAction,
        move: hostOwnedAction,
        scroll: hostOwnedAction,
        type: hostOwnedAction,
        wait: hostOwnedAction,
      },
    });
  }
  if (definition.type !== "function")
    throw new Error("Unsupported computer proposal tool");
  const { name, description, parameters, strict } = definition;
  return tool({
    name,
    description,
    parameters,
    strict,
    needsApproval: true,
    execute: hostOwnedAction,
  });
}

async function proposeComputerActions({ request, dispatch, signal }) {
  const agent = new Agent({
    name: "Runner",
    tools: request.tools.map(computerActionTool),
    modelSettings: {
      reasoning: request.reasoning,
      maxTokens: request.max_output_tokens,
      toolChoice: request.tool_choice?.name,
      ...(request.prompt_cache_options && {
        providerData: { prompt_cache_options: request.prompt_cache_options },
      }),
    },
  });
  let dispatched = false;
  const runner = retainedRunner(
    {
      model: request.model,
      store: false,
      dispatch: (wire, options) => {
        if (dispatched) throw new Error("Computer turn already dispatched");
        dispatched = true;
        return dispatch(wire, options);
      },
    },
    ComputerProposalModel,
  );
  const input = request.input.map((item) => ({
    type: "unknown",
    providerData: item,
    ...(item.id ? { id: item.id } : {}),
  }));
  try {
    await runner.run(agent, input, {
      signal,
      previousResponseId: request.previous_response_id,
      maxTurns: 1,
    });
  } catch (error) {
    if (error instanceof ComputerProposalReceived) return error.callIds;
    throw error;
  }
  throw new Error("Computer agent ended without a model proposal");
}

// Completed action proposals use SDK protocol conversion. Terminal replies
// belong to the host so it can retain provider errors and report its outcome.
class TerminalComputerResponse extends Error {}

export async function requestComputerActionTurn({
  request,
  signal,
  dispatch,
  isTerminal,
}) {
  let original;
  let proposalIds;
  let calls;
  try {
    proposalIds = await proposeComputerActions({
      request,
      signal,
      dispatch: async (wire) => {
        // The SDK explicitly lists no required arguments for an empty object.
        // Compare that equivalent schema, then send the owner's exact bytes.
        const tools = request.tools.map((def) => {
          const schema = def.parameters;
          if (
            def.type === "function" &&
            def.strict === true &&
            schema?.type === "object" &&
            schema.properties &&
            Object.keys(schema.properties).length === 0 &&
            schema.required === undefined
          ) {
            return { ...def, parameters: { ...schema, required: [] } };
          }
          return def;
        });
        const expected = {
          ...request,
          tools,
          store: false,
          stream: false,
          include: [],
        };
        if (!isDeepStrictEqual(JSON.parse(JSON.stringify(wire)), expected))
          throw new Error(
            "Computer agent request differs from its retained request",
          );
        original = await dispatch();
        if (
          !original.response.ok ||
          original.body?.status !== "completed" ||
          !Array.isArray(original.body.output) ||
          isTerminal?.(original.body.output)
        ) {
          throw new TerminalComputerResponse();
        }
        calls = original.body.output.filter(isActionCall);
        if (!calls.length) throw new TerminalComputerResponse();
        // The SDK checks only the action proposals. The host reads the full reply.
        return { ...original.body, output: calls };
      },
    });
  } catch (error) {
    if (error instanceof TerminalComputerResponse) return original;
    throw error;
  }
  if (
    !isDeepStrictEqual(
      proposalIds,
      calls.map((item) => item.call_id),
    )
  )
    throw new Error("Computer agent changed the proposed action sequence");
  return original;
}
